func newEvent() unsafe.Pointer { return unsafe.Pointer(new(shipmentevent.Event)) }

func newNEvent(n int) unsafe.Pointer {
	return unsafe.Pointer(unsafe.SliceData(make([]shipmentevent.Event, n)))
}

func ptrEvent(p unsafe.Pointer, c int32) any {
	r := (*shipmentevent.Event)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 2:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 3:
		return (*string)(unsafe.Pointer(&r.ShipmentID))
	case 4:
		return (*string)(unsafe.Pointer(&r.MoveID))
	case 5:
		return (*string)(unsafe.Pointer(&r.StopID))
	case 6:
		return (*string)(unsafe.Pointer(&r.AssignmentID))
	case 7:
		return (*string)(unsafe.Pointer(&r.CommentID))
	case 8:
		return (*string)(unsafe.Pointer(&r.HoldID))
	case 9:
		return (*string)(unsafe.Pointer(&r.Type))
	case 10:
		return (*string)(unsafe.Pointer(&r.Severity))
	case 11:
		return (*string)(unsafe.Pointer(&r.ActorType))
	case 12:
		return (*string)(unsafe.Pointer(&r.ActorID))
	case 13:
		return &r.ActorLabel
	case 14:
		return &r.Summary
	case 15:
		return &r.Metadata
	case 16:
		return &r.OccurredAt
	case 17:
		return &r.CorrelationID
	}
	return nil
}

func valueEvent(p unsafe.Pointer, c int32) any {
	r := (*shipmentevent.Event)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return string(r.OrganizationID)
	case 3:
		return string(r.ShipmentID)
	case 4:
		if r.MoveID == "" {
			return nil
		}
		return string(r.MoveID)
	case 5:
		if r.StopID == "" {
			return nil
		}
		return string(r.StopID)
	case 6:
		if r.AssignmentID == "" {
			return nil
		}
		return string(r.AssignmentID)
	case 7:
		if r.CommentID == "" {
			return nil
		}
		return string(r.CommentID)
	case 8:
		if r.HoldID == "" {
			return nil
		}
		return string(r.HoldID)
	case 9:
		return string(r.Type)
	case 10:
		return string(r.Severity)
	case 11:
		return string(r.ActorType)
	case 12:
		if r.ActorID == "" {
			return nil
		}
		return string(r.ActorID)
	case 13:
		if r.ActorLabel == "" {
			return nil
		}
		return r.ActorLabel
	case 14:
		return r.Summary
	case 15:
		if r.Metadata == nil {
			return keel.EmptyJSONObject
		}
		return r.Metadata
	case 16:
		return r.OccurredAt
	case 17:
		if r.CorrelationID == "" {
			return nil
		}
		return r.CorrelationID
	}
	return nil
}

func attachEvent(p unsafe.Pointer, rel int32, child unsafe.Pointer) {
	r := (*shipmentevent.Event)(p)
	switch rel {
	case 0:
		r.Actor = (*tenant.User)(child)
	case 1:
		r.Shipment = (*shipment.Shipment)(child)
	}
}

func beforeCreateEvent(ctx context.Context, p unsafe.Pointer) error {
	return (*shipmentevent.Event)(p).BeforeCreate(ctx)
}

func init() {
	eventsTable.Relations[0].Target = tenantdb.UsersSchema()
	eventsTable.Relations[1].Target = shipmentdb.ShipmentsSchema()
}

